mapper.select:
WITH bucket_def(label, ord) AS ( VALUES ('未到期', 1), ('0-30天', 2), ('31-90天', 3), ('91-180天', 4), ('180天以上', 5) ), aged AS ( SELECT CASE WHEN b.due_date > #{refDate} THEN '未到期' WHEN (#{refDate} - b.due_date) <= 30 THEN '0-30天' WHEN (#{refDate} - b.due_date) <= 90 THEN '31-90天' WHEN (#{refDate} - b.due_date) <= 180 THEN '91-180天' ELSE '180天以上' END AS label, count(*) AS bill_count, count(DISTINCT b.house_id) AS houses, coalesce(sum(b.payable - b.waive_amount - b.paid_amount), 0) AS owed_amount FROM bill b WHERE b.deleted_at IS NULL AND b.status IN ('待缴', '部分缴')
AND b.community_id = #{communityId}
GROUP BY 1 ) SELECT d.label AS bucket, coalesce(a.bill_count, 0) AS bill_count, coalesce(a.houses, 0) AS houses, coalesce(a.owed_amount, 0) AS owed_amount FROM bucket_def d LEFT JOIN aged a ON a.label = d.label ORDER BY d.ord

SELECT b.community_id AS community_id, max(c.name) AS community_name, count(DISTINCT b.house_id) AS houses, coalesce(sum(b.payable - b.waive_amount - b.paid_amount), 0) AS owed_amount FROM bill b LEFT JOIN community c ON c.tenant_id = b.tenant_id AND c.community_id = b.community_id WHERE b.deleted_at IS NULL AND b.status IN ('待缴', '部分缴')
AND b.community_id = #{communityId}
GROUP BY b.community_id ORDER BY b.community_id

SELECT b.bill_no AS bill_id, btrim(b.period) AS period, b.due_date AS due_date, CASE WHEN b.due_date > #{refDate} THEN '未到期' WHEN (#{refDate} - b.due_date) <= 30 THEN '0-30天' WHEN (#{refDate} - b.due_date) <= 90 THEN '31-90天' WHEN (#{refDate} - b.due_date) <= 180 THEN '91-180天' ELSE '180天以上' END AS aging, (#{refDate} - b.due_date) AS overdue_days, (b.payable - b.waive_amount - b.paid_amount) AS unpaid FROM bill b WHERE b.deleted_at IS NULL AND b.status IN ('待缴', '部分缴')
AND b.community_id = #{communityId}
ORDER BY b.due_date ASC, b.bill_no ASC LIMIT #{limit}
